import {progressDetails,progressCoverage} from './progress-analysis.mjs';
import {progressFloors,progressFloor} from './progress-scope.mjs';
import {loadPma} from './pma.mjs';
import {nivel} from './level.mjs';
import {tasksFor,keyFor,installation,quality,fields,reportProgress} from './room-progress-model.mjs';
import {readProgress,saveProgress,exportProgress,importProgress} from './room-progress-store.mjs';
import {workChart} from './work-charts.mjs';
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'America/Santiago',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const options=(values,current,esc)=>values.map(v=>`<option ${v===current?'selected':''}>${esc(v)}</option>`).join('');
const download=value=>{const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='Atlas-avance-'+nivel.id+'-'+today()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);};
export async function renderRoomProgress(root,room,esc,afterSave=()=>{}){
 if(!progressFloors[nivel.id]||progressFloor(room.level)!==nivel.id){root.textContent='El recinto no pertenece al piso activo.';return;}
 const serial=(Number(root.dataset.progressSerial)||0)+1;root.dataset.progressSerial=serial;root.textContent='Cargando checklist…';
 try{
 const [model,snapshot]=await Promise.all([loadPma(),readProgress()]);if(!root.isConnected||Number(root.dataset.progressSerial)!==serial)return;
 const current=snapshot.records.find(r=>r.key===keyFor(room.code,nivel.id)),version=current?.version||0,tasks=tasksFor(model,room,nivel.id),summary=reportProgress(model,[room],snapshot.records,nivel.id).rows[0],draftKey='atlas-room-draft:'+keyFor(room.code,nivel.id);
 let draft;try{draft=JSON.parse(sessionStorage.getItem(draftKey));}catch{}
 const compatible=draft&&draft.version===version&&draft.sourceSha===model.source.sha256,base=compatible?draft:current;
 root.innerHTML=`<h3>Avance en terreno · ${esc(nivel.nombre)}</h3><p>${esc(room.code)} · ${esc(room.name)}</p><p class="muted">Guardado en este dispositivo. Cada partida registra instalación y revisión por separado.</p>${summary.warnings.map(w=>`<p class="pmaWarning">${esc(w)}</p>`).join('')}${draft?`<p>${compatible?'Borrador recuperado; aún no guardado.':'Hay un borrador de otra versión. Descárgalo antes de reemplazarlo.'}</p><button type="button" id="downloadRoomDraft">Descargar borrador</button>`:''}<form id="roomProgressForm"><label>Responsable<input name="responsible" required maxlength="200" value="${esc(base?.responsible||'')}"></label><label>Fecha de revisión<input name="date" type="date" required value="${esc(base?.date||today())}"></label>${tasks.map(t=>{const v=base?.fields?.[t.field],same=base?.sourceSha===model.source.sha256&&v?.code===t.code;return `<details class="progressTask" ${t.field==='PAV'?'open':''}><summary>${esc(t.name)} · ${esc(t.code||'Sin código')} · ${esc(same?v.installation:'Sin registrar')}</summary><p>${esc(t.description)}${t.field!=='PAV'?'<br>Asepsia de pintura requerida: '+esc(t.asepsis||'Sin dato'):''}</p>${!t.applicable?'<p>No aplica según PMA; fuera del cálculo.</p>':!t.documented?'<p>Requiere definición documental; fuera del porcentaje y bloquea recinto completo.</p>':`<label>Instalación<select name="${t.field}_installation">${options(installation,same?v.installation:'Sin registrar',esc)}</select></label><label>Condición / revisión<select name="${t.field}_quality">${options(quality,same?v.quality:'Sin revisar',esc)}</select></label><label>Qué falta<textarea name="${t.field}_missing" maxlength="5000">${esc(v?.missing||'')}</textarea></label><label>Observaciones de esta partida<textarea name="${t.field}_notes" maxlength="5000">${esc(v?.notes||'')}</textarea></label>`}</details>`;}).join('')}${!tasks.length?'<p>No hay correspondencia PMA para generar partidas.</p>':''}<label>Observaciones generales del recinto<textarea name="notes" maxlength="10000">${esc(base?.notes||'')}</textarea></label>${summary.warnings.length||current&&current.sourceSha!==model.source.sha256?'<label class="check"><input name="sourceReviewed" type="checkbox" required> Cotejé las diferencias documentales antes de registrar el avance.</label>':''}<p class="progressFeedback" role="status"></p><div class="actions"><button type="submit" ${!tasks.length?'disabled':''}>Guardar avance</button><button type="button" id="discardRoomDraft">Descartar borrador</button></div></form><details><summary>Historial de este recinto</summary>${snapshot.history.filter(h=>h.record.key===keyFor(room.code,nivel.id)).sort((a,b)=>b.record.version-a.record.version).map(h=>`<article><b>Versión ${h.record.version} · ${esc(h.record.date)} · ${esc(h.record.responsible)}</b><p>${esc(h.record.notes)}</p>${Object.entries(h.record.fields).map(([f,v])=>`<p>${esc(fields[f])}: ${esc(v.installation)} · ${esc(v.quality)}<br>Falta: ${esc(v.missing)}<br>${esc(v.notes)}</p>`).join('')}</article>`).join('')||'<p>Sin registros guardados.</p>'}</details>`;
 const form=root.querySelector('form'),feedback=root.querySelector('.progressFeedback');if(draft&&!compatible)form.querySelectorAll('input,select,textarea,button[type=submit]').forEach(e=>e.disabled=true);
 const values=()=>{const f=new FormData(form);return {key:keyFor(room.code,nivel.id),code:room.code,level:nivel.id,sourceSha:model.source.sha256,version,responsible:String(f.get('responsible')||''),date:String(f.get('date')||''),sourceReviewed:f.has('sourceReviewed'),notes:String(f.get('notes')||''),fields:Object.fromEntries(tasks.filter(t=>t.applicable&&t.documented).map(t=>[t.field,{code:t.code,installation:f.get(t.field+'_installation'),quality:f.get(t.field+'_quality'),missing:String(f.get(t.field+'_missing')||''),notes:String(f.get(t.field+'_notes')||'')}]))};};
 form.oninput=()=>{try{sessionStorage.setItem(draftKey,JSON.stringify(values()));feedback.textContent='Borrador conservado en esta pestaña. Pulsa Guardar avance para incorporarlo a los gráficos.';}catch{feedback.textContent='No se pudo conservar el borrador. Guarda antes de salir.';}};
 root.querySelector('#downloadRoomDraft')?.addEventListener('click',()=>download({format:'atlas-room-progress-draft',draft}));
 root.querySelector('#discardRoomDraft').onclick=()=>{sessionStorage.removeItem(draftKey);renderRoomProgress(root,room,esc,afterSave);};
 form.onsubmit=async e=>{e.preventDefault();const button=form.querySelector('[type=submit]');button.disabled=true;try{const value={...values(),version:version+1,at:new Date().toISOString()};await saveProgress(value,version);sessionStorage.removeItem(draftKey);await renderRoomProgress(root,room,esc,afterSave);if(root.isConnected)root.querySelector('.progressFeedback').textContent='Avance guardado con historial.';afterSave();}catch(error){feedback.textContent=error.message;button.disabled=false;}};
 }catch(error){if(root.isConnected){root.textContent=error.message;const b=document.createElement('button');b.textContent='Reintentar';b.onclick=()=>renderRoomProgress(root,room,esc,afterSave);root.append(b);}}
}
export async function renderProgressControl(root,ctx,initial={}){
 if(!progressFloors[nivel.id]){root.textContent='Elige un piso de trabajo.';return;}
 root.textContent='Cargando avance de '+nivel.nombre+'…';
 try{const model=await loadPma();let snapshot=await readProgress(),query='',sector='',status=initial.status||'',family='',asepsis='',filtersOpen=false,selected=null,focus=initial.focus||null,detailPage=0;const esc=ctx.esc;
 const refresh=async()=>{snapshot=await readProgress();if(root.isConnected)draw();};
 function draw(){if(!root.isConnected)return;const all=reportProgress(model,ctx.rooms(),snapshot.records,nivel.id);let rows=all.rows.filter(r=>(!sector||r.room.sector===sector)&&(!asepsis||r.tasks.some(t=>t.asepsis===asepsis))&&(!query||[r.room.code,r.room.name].join(' ').toLowerCase().includes(query.toLowerCase()))&&(!status||(status==='complete'?r.complete:status==='observed'?r.tasks.some(t=>t.quality==='Con observaciones'):status==='unregistered'?r.tasks.some(t=>t.installation==='Sin registrar'):!r.complete)));
 const tasks=rows.flatMap(r=>r.tasks).filter(t=>t.documented&&(!family||t.field===family)),installed=tasks.filter(t=>t.installation==='Instalado').length,accepted=tasks.filter(t=>t.installation==='Instalado'&&t.quality==='Conforme').length;
 const coverage=progressCoverage(rows,family);
 const items=values=>values.map(([key,n],i)=>({key,n,color:['#8a9eaa','#bc9863','#357d9a','#4c8a6b'][i%4]}));
 root.innerHTML=`<div class="documentaryIntro"><h2>Avance por recinto · ${esc(nivel.nombre)}</h2><p>${all.rows.length} recintos del plano de ${esc(nivel.nombre)} · PMA ${esc(progressFloors[nivel.id])}. Registros de este dispositivo; exporta el respaldo para conservarlos o trasladarlos.</p></div><div class="actions"><button id="progressRefresh">Actualizar avance</button><button id="progressExport">Exportar respaldo de este piso</button><label class="progressImportLabel">Importar respaldo<input id="progressImport" type="file" accept="application/json,.json"></label></div><details class="progressFilters" ${filtersOpen?'open':''}><summary>Filtrar avance / buscar recinto</summary><div class="pmaFilters"><label>Recinto<input id="progressQuery" type="search" value="${esc(query)}"></label><label>Sector<select id="progressSector"><option value="">Todos</option>${options([...new Set(all.rows.map(r=>r.room.sector))].sort(),sector,esc)}</select></label><label>Partida<select id="progressFamily"><option value="">Todas</option>${Object.entries(fields).map(([f,n])=>`<option value="${f}" ${family===f?'selected':''}>${n}</option>`).join('')}</select></label><label>Recintos<select id="progressStatus">${[['','Todos'],['complete','Completos y conformes'],['pending','Pendientes'],['observed','Con observaciones'],['unregistered','Sin registrar']].map(([v,l])=>`<option value="${v}" ${status===v?'selected':''}>${l}</option>`).join('')}</select></label><label>Asepsia requerida<select id="progressAsepsis"><option value="">Todas</option>${options([...new Set(all.rows.flatMap(r=>r.tasks.map(t=>t.asepsis)).filter(Boolean))].sort(),asepsis,esc)}</select></label></div></details><p id="progressMessage" role="status"></p><div class="kpiGrid">${[[installed+' / '+tasks.length,'Partidas instaladas','installed'],[accepted+' / '+tasks.length,'Instaladas y conformes','accepted'],[rows.filter(r=>r.complete).length+' / '+rows.length,'Recintos completos y conformes','complete'],[tasks.filter(t=>t.quality==='Con observaciones').length,'Partidas con observaciones','observed']].map(([n,label,key])=>`<button type="button" class="kpi progressKpi" data-progress-insight="${key}" aria-controls="progressEvidence"><span>${label}</span><b>${n}</b><small>Ver detalle ↗</small></button>`).join('')}</div><p>Instalación: ${tasks.length?(100*installed/tasks.length).toFixed(1)+'%':'sin base'} · Conformidad: ${tasks.length?(100*accepted/tasks.length).toFixed(1)+'%':'sin base'}. Cada partida cuenta una vez, sin ponderación por superficie o costo. En proceso no se convierte en un porcentaje arbitrario. ${all.unknown} partidas sin definición documental. ${all.withoutPma} recintos sin correspondencia PMA válida en este piso; no se generan partidas para ellos.</p><p class="progressCoverage"><b>Cobertura del levantamiento: ${coverage.recorded} / ${coverage.total} partidas con estado registrado.</b> ${coverage.unregistered} sin registrar; no equivalen a trabajo no iniciado. ${coverage.awaitingReview} instaladas esperan revisión.${coverage.stale?' '+coverage.stale+' registros requieren cotejar una fuente actualizada.':''}</p><p class="dataNote">Toca un indicador, un estado del gráfico, una familia o un sector para consultar sus partidas y abrir el recinto.</p><div class="chartGrid">${workChart({title:'Instalación de partidas',kind:'pie',filter:'progress-installation',items:items(installation.map(s=>[s,tasks.filter(t=>t.installation===s).length])),emptyText:'Sin partidas en este filtro.'},esc)}${workChart({title:'Instaladas pendientes de revisión o corrección',filter:'progress-quality',items:items(quality.map(s=>[s,tasks.filter(t=>t.installation==='Instalado'&&t.quality===s).length])),emptyText:'Todavía no hay partidas instaladas en este filtro.'},esc)}<section class="chartCard"><h3>Avance por partida</h3><p>Instaladas / conformes / total aplicable</p>${Object.entries(fields).filter(([f])=>!family||family===f).map(([f,n])=>{const ts=tasks.filter(t=>t.field===f),done=ts.filter(t=>t.installation==='Instalado').length,ok=ts.filter(t=>t.installation==='Instalado'&&t.quality==='Conforme').length;return `<div class="progressFamily"><button type="button" data-progress-family="${f}" aria-controls="progressEvidence">${n} ↗</button><span>${done} / ${ok} / ${ts.length}</span><progress aria-label="${n}: ${done} instaladas de ${ts.length}" value="${done}" max="${ts.length||1}"></progress></div>`;}).join('')}</section>${workChart({title:'Trabajo pendiente por sector',filter:'progress-sector',items:items([...new Set(rows.map(r=>r.room.sector||'Sin sector'))].map(s=>['Sector '+s,rows.filter(r=>(r.room.sector||'Sin sector')===s).flatMap(r=>r.tasks).filter(t=>t.documented&&(!family||t.field===family)&&!(t.installation==='Instalado'&&t.quality==='Conforme')).length]).sort((a,b)=>b[1]-a[1])),subtitle:'Incluye sin registrar, en proceso y partidas que requieren revisión.',emptyText:'Sin pendientes en esta consulta.'},esc)}</div><section id="progressEvidence" class="chartCard progressEvidence" hidden aria-label="Partidas del indicador seleccionado"></section><details class="workRecords" open><summary>Checklist de recintos · ${rows.length}</summary><p>Un recinto completo exige todas sus partidas aplicables instaladas y conformes. La familia filtra partidas; el criterio de recinto completo abarca todas sus terminaciones.</p><div class="progressRoomList">${rows.map(r=>`<button data-progress-room="${esc(r.room.id)}">${esc(r.room.code)} · ${esc(r.room.name)}<small>${r.complete?'Completo y conforme':r.tasks.filter(t=>t.installation==='Instalado').length+'/'+r.tasks.filter(t=>t.documented).length+' partidas instaladas'}${r.warnings.length?' · Diferencias documentales':''}</small></button>`).join('')||'<p>Sin resultados.</p>'}</div></details><section id="progressEditor" class="chartCard" ${selected?'':'hidden'}></section>`;
 for(const [id,key] of [['progressSector','sector'],['progressFamily','family'],['progressStatus','status'],['progressAsepsis','asepsis']])root.querySelector('#'+id).onchange=e=>{focus=null;detailPage=0;if(key==='sector')sector=e.target.value;if(key==='family')family=e.target.value;if(key==='status')status=e.target.value;if(key==='asepsis')asepsis=e.target.value;selected=null;draw();};
 root.querySelector('.progressFilters').ontoggle=e=>{filtersOpen=e.target.open;};
 root.querySelector('#progressQuery').oninput=e=>{query=e.target.value;focus=null;detailPage=0;selected=null;draw();const input=root.querySelector('#progressQuery');input.focus();input.setSelectionRange(query.length,query.length);};
 root.querySelectorAll('[data-progress-room]').forEach(b=>b.onclick=()=>{selected=ctx.rooms().find(r=>r.id===b.dataset.progressRoom);const editor=root.querySelector('#progressEditor');editor.hidden=false;renderRoomProgress(editor,selected,esc,()=>refresh());editor.scrollIntoView({block:'start'});});
 root.querySelector('#progressRefresh').onclick=refresh;
 root.querySelector('#progressExport').onclick=async()=>{try{download(await exportProgress(nivel.id));}catch(e){root.querySelector('#progressMessage').textContent=e.message;}};
 root.querySelector('#progressImport').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>20*1024*1024)throw Error('Respaldo demasiado grande');await importProgress(JSON.parse(await f.text()));await refresh();root.querySelector('#progressMessage').textContent='Respaldo importado.';}catch(error){root.querySelector('#progressMessage').textContent=error.message;}};
 function renderEvidence(){
  const target=root.querySelector('#progressEvidence');
  root.querySelectorAll('[data-progress-insight]').forEach(b=>b.setAttribute('aria-pressed',String(focus?.kind===b.dataset.progressInsight)));
  root.querySelectorAll('[data-work-filter]').forEach(b=>b.setAttribute('aria-pressed',String(focus?.chart===b.dataset.workFilter&&focus?.value=== (b.dataset.workFilter==='progress-sector'?b.dataset.workState.slice(7):b.dataset.workState))));
  if(!focus){target.hidden=true;target.replaceChildren();return;}
  const details=progressDetails(rows,family,focus),pages=Math.max(1,Math.ceil(details.length/25));detailPage=Math.min(detailPage,pages-1);const pageRows=details.slice(detailPage*25,detailPage*25+25),roomCount=new Set(details.map(d=>d.room.id)).size;
  const labels={installed:'Partidas instaladas',accepted:'Instaladas y conformes',complete:'Recintos completos y conformes',observed:'Partidas con observaciones',all:family?fields[family]:'Todas las partidas',installation:focus.value,quality:'Instaladas · '+focus.value,sector:'Pendientes · Sector '+focus.value};
  target.hidden=false;target.innerHTML=`<div class="chartHeading"><h3>${esc(labels[focus.kind])}</h3><button type="button" id="closeProgressEvidence">Cerrar detalle</button></div><p role="status" id="progressEvidenceCount">${details.length} ${details.length===1?'partida':'partidas'} · ${roomCount} ${roomCount===1?'recinto':'recintos'} · ${esc(nivel.nombre)}${family?' · '+esc(fields[family]):''}</p><p>Los indicadores mantienen su base. Este listado muestra las partidas del criterio seleccionado dentro de tus filtros.</p><div class="tableScroll"><table class="progressEvidenceTable"><thead><tr><th>Recinto</th><th>Partida / material</th><th>Instalación</th><th>Condición</th><th>Última revisión</th><th>Acciones</th></tr></thead><tbody>${pageRows.map(({room,task,record})=>`<tr><td data-label="Recinto"><b>${esc(room.code)}</b><br>${esc(room.name)}</td><td data-label="Partida / material">${esc(fields[task.field])} · ${esc(task.code)}<br>${esc(task.description)}</td><td data-label="Instalación">${esc(task.installation)}</td><td data-label="Condición">${esc(task.quality)}${task.missing?'<br>Falta: '+esc(task.missing):''}${task.notes?'<br>'+esc(task.notes):''}</td><td data-label="Última revisión">${task.stale?'Fuente cambiada: requiere cotejo':record?esc(record.date+' · '+record.responsible):'Sin revisión registrada'}</td><td data-label="Acciones"><button type="button" data-progress-evidence-room="${esc(room.id)}">Revisar avance</button>${ctx.locate?`<button type="button" data-progress-locate="${esc(room.id)}">Ver recinto en plano</button>`:''}</td></tr>`).join('')||'<tr><td colspan="6">Sin partidas para este criterio y estos filtros.</td></tr>'}</tbody></table></div><div class="pagination"><button type="button" id="progressEvidencePrev" ${detailPage===0?'disabled':''}>Anterior</button><span>Página ${detailPage+1} de ${pages}</span><button type="button" id="progressEvidenceNext" ${detailPage+1===pages?'disabled':''}>Siguiente</button></div>`;
  target.querySelector('#closeProgressEvidence').onclick=()=>{focus=null;renderEvidence();};target.querySelector('#progressEvidencePrev').onclick=()=>{detailPage--;renderEvidence();};target.querySelector('#progressEvidenceNext').onclick=()=>{detailPage++;renderEvidence();};
  target.querySelectorAll('[data-progress-evidence-room]').forEach(b=>b.onclick=()=>{selected=ctx.rooms().find(r=>r.id===b.dataset.progressEvidenceRoom);const editor=root.querySelector('#progressEditor');editor.hidden=false;renderRoomProgress(editor,selected,esc,()=>refresh());editor.scrollIntoView({block:'start'});});
  target.querySelectorAll('[data-progress-locate]').forEach(b=>b.onclick=()=>ctx.locate(b.dataset.progressLocate));
 }
 const reveal=next=>{focus=next;detailPage=0;renderEvidence();root.querySelector('#progressEvidence').scrollIntoView({block:'start'});};
 root.querySelectorAll('[data-progress-insight]').forEach(b=>b.onclick=()=>reveal({kind:b.dataset.progressInsight}));
 root.querySelectorAll('[data-work-filter]').forEach(b=>{const apply=()=>{const type=b.dataset.workFilter;reveal({kind:type==='progress-quality'?'quality':type==='progress-sector'?'sector':'installation',value:type==='progress-sector'?b.dataset.workState.slice(7):b.dataset.workState,chart:type});};b.onclick=apply;if(b.tagName!=='BUTTON')b.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();apply();}};});
 root.querySelectorAll('[data-progress-family]').forEach(b=>b.onclick=()=>{family=b.dataset.progressFamily;selected=null;focus={kind:'all'};detailPage=0;draw();root.querySelector('#progressEvidence').scrollIntoView({block:'start'});});
 renderEvidence();
 if(selected)renderRoomProgress(root.querySelector('#progressEditor'),selected,esc);
 }
 draw();
 if(root.isConnected&&initial.focus)root.querySelector('#progressEvidence')?.scrollIntoView({block:'start'});
 }catch(error){if(root.isConnected){root.textContent=error.message;const b=document.createElement('button');b.textContent='Reintentar';b.onclick=()=>renderProgressControl(root,ctx,initial);root.append(b);}}
}
